{
  "name": "opencode-qoder-plugin",
  "version": "0.2.3",
  "description": "opencode plugin — Qoder AI models with bundled SDK, zero config required",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts",
    "./provider": "./provider.ts"
  },
  "dependencies": {
    "@ai-sdk/provider": "^3.0.8",
    "@opencode-ai/plugin": "^1.2.27",
    "zod": "^3.22.4"
  },
  "devDependencies": {
    "@types/node": "^20.4.5",
    "vitest": "^4.0.15"
  },
  "author": "yee.wang <wyy.xb@qq.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/yee94/opencode-qoder-provider.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "qoder",
    "ai",
    "plugin"
  ],
  "engines": {
    "node": ">=20.0.0"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  },
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest",
    "vendor:patch-sdk": "node ./scripts/patch-qoder-agent-sdk.mjs"
  }
}
